<template><div class="page-wrap"><page-section title="移动执行配置"><template slot="extra"><el-button size="small" type="primary" @click="edit()">新增配置</el-button><el-button size="small" @click="fetchList">刷新</el-button></template><el-form :inline="true" size="small" @submit.native.prevent><el-form-item label="项目"><el-select v-model="projectId" clearable filterable placeholder="全部项目" style="width:220px"><el-option v-for="item in projects" :key="item.id" :label="item.name" :value="String(item.id)" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="fetchList">查询</el-button></el-form-item></el-form><el-table v-loading="loading" :data="rows" border style="width:100%"><el-table-column prop="name" label="配置名称" min-width="190"/><el-table-column label="项目" min-width="130"><template slot-scope="scope">{{ projectName(scope.row.project_id) }}</template></el-table-column><el-table-column label="应用" min-width="180" show-overflow-tooltip><template slot-scope="scope">{{ scope.row.mobile_app_id }}</template></el-table-column><el-table-column prop="device_serial" label="设备" min-width="160" show-overflow-tooltip/><el-table-column prop="env_code" label="环境" width="100"/><el-table-column label="测试用例" min-width="180"><template slot-scope="scope">{{ (scope.row.case_ids || []).length }} 个</template></el-table-column><el-table-column prop="script_selector" label="脚本选择器" min-width="260" show-overflow-tooltip/><el-table-column prop="updated_time" label="更新时间" min-width="165"/><el-table-column label="操作" width="230" fixed="right"><template slot-scope="scope"><el-button type="text" @click="edit(scope.row)">编辑</el-button><el-button type="text" @click="run(scope.row)">执行</el-button><el-button type="text" class="danger" @click="remove(scope.row)">删除</el-button></template></el-table-column></el-table><div class="pager"><el-pagination background layout="total, prev, pager, next" :current-page="pageNo" :page-size="pageSize" :total="total" @current-change="page=>{pageNo=page;fetchList()}" /></div></page-section></div></template>
<script>
import PageSection from '@/components/TestPlatform/common/PageSection'
import { getProjectList } from '@/api/projectApi'
import { deleteMobileExecutionConfig, getMobileExecutionConfigList, runMobileExecutionConfig } from '@/api/mobileAutomationApi'
export default{name:'MobileAutomationExecutionConfigList',components:{PageSection},data(){return{loading:false,rows:[],projects:[],projectId:'',pageNo:1,pageSize:20,total:0}},created(){getProjectList({pageNo:1,pageSize:500}).then(res=>{const d=this.dataOf(res);this.projects=d.list||d.items||[]});this.fetchList()},methods:{dataOf(res){return(res&&res.data)||res||{}},fetchList(){this.loading=true;getMobileExecutionConfigList(Object.assign({page_no:this.pageNo,page_size:this.pageSize},this.projectId?{project_id:this.projectId}:{})).then(res=>{const d=this.dataOf(res);this.rows=d.list||[];this.total=Number(d.total||0)}).finally(()=>{this.loading=false})},projectName(id){const item=this.projects.find(v=>String(v.id)===String(id));return item?item.name:id||'-'},edit(row){this.$router.push({path:'/mobile-automation/run/edit',query:row?{id:row.id}:{}})},run(row){this.$confirm('将使用此配置创建新的移动执行，是否继续？','执行配置',{type:'warning'}).then(()=>runMobileExecutionConfig(row.id)).then(res=>{const d=this.dataOf(res);this.$message.success('移动执行已创建');this.$router.push({path:'/mobile-automation/execution/detail',query:{execution_id:d.id}})}).catch(()=>{})},remove(row){this.$confirm('删除后不会影响历史执行记录，是否继续？','删除配置',{type:'warning'}).then(()=>deleteMobileExecutionConfig(row.id)).then(()=>{this.$message.success('配置已删除');this.fetchList()}).catch(()=>{})}}}
</script><style scoped>.pager{margin-top:16px;text-align:right}.danger{color:#f56c6c}</style>
